baseline = namespace['_matmul']

def candidate(left, right):
    result = []
    for index in range(4):
        row = left[index]
        result.append([
            sum((row[0] * right[0][column], row[1] * right[1][column],
                 row[2] * right[2][column], row[3] * right[3][column]))
            for column in range(4)
        ])
    return result

